import pages
def run_series(base,parts,theme,series,sign,short,out):
    PG.configure(base,parts,theme,series,sign,short); PG.OUT=out
# ================= GURU PŪRṆIMĀ
run_series('/festivals/guru-purnima/',[('vyasa-purnima','Vyāsa Pūrṇimā','The Sage Who Arranged the Veda'),('the-guru','The Guru','“Gurur Brahmā” and the Silent Teacher'),('chaturmasya','Cāturmāsya Begins','The Ascetics’ Rainy-Season Retreat')],'navy','Guru Pūrṇimā','Lord','Guru Pūrṇimā','outx/guru-purnima/')
L=pages.link
GV=[itrans(x) for x in ["gururbrahmA gururviShNurgururdevo maheshvaraH |","gurureva paraM brahma tasmai shrIgurave namaH || 58||","aj~nAnatimirAndhasya j~nAnA~njanashalAkayA |","chakShurunmIlitaM yena tasmai shrIgurave namaH || 59||","akhaNDamaNDalAkAraM vyAptaM yena charAcharam |","tatpadaM darshitaM yena tasmai shrIgurave namaH || 60||"]]
VY=lambda: sage('#ff8c1a')
i=0
COV=covart('The sage Vyāsa seated under a tree dictating, with four bundles of palm-leaf books for the four Vedas and Gaṇeśa writing',g(130,196,1.3,VY())+g(250,196,1.1,'<circle cy="-30" r="22" fill="#f4a6b8" stroke="#111" stroke-width="2"/><path d="M14 -24 q16 10 4 26" fill="none" stroke="#f4a6b8" stroke-width="8"/>'+book())+''.join(g(320+k*28,196,.6,book()) for k in range(4))+g(60,196,1.2,tree()))
pp=[foreword(i,['On the full moon of Āṣāḍha, Hindus, Buddhists and Jains honour their teachers. For Hindus it is <b>Guru Pūrṇimā</b>, also called <b>Vyāsa Pūrṇimā</b>, the birthday of the sage <b>Vyāsa</b>, who arranged the Veda and composed the Mahābhārata.','This 3-part series covers Vyāsa, the idea of the guru with its most famous verses, and the start of <b>Cāturmāsya</b>, the rainy-season retreat of the sannyāsins.'],[('z','Why a day for teachers?'),('b','Because nothing in the tradition is learned alone. Every chant, every verse came through a teacher.')]),
 glance([('When','Full moon of Āṣāḍha (June–July)'),('Names','Guru Pūrṇimā, Vyāsa Pūrṇimā'),('Honoured','Vyāsa, and every teacher (guru)'),('Vyāsa','Arranged the Veda into four; composed the Mahābhārata; credited with the Purāṇas and Brahma Sūtra'),('Customs','Guru pūjā, Vyāsa pūjā in maṭhas, students honour teachers'),('Also','Cāturmāsya begins for sannyāsins')],svg(560,140,'A full moon over a seated sage',g(280,130,1.2,VY())+g(420,40,1,'<circle r="24" fill="#fff8d0" stroke="#111" stroke-width="2"/>'))),
 reading('who','WHO WAS VYĀSA','Kṛṣṇa Dvaipāyana',svg(560,170,'A young dark-skinned sage born on an island in a river',river(560,120)+g(280,130,1,'<ellipse rx="80" ry="20" fill="#8a9a6a" stroke="#111" stroke-width="2"/>')+g(280,120,1,sage('#3a3a52'))),['<b>His name.</b> He was born <b>Kṛṣṇa Dvaipāyana</b>: Kṛṣṇa because he was dark, Dvaipāyana because he was born on an island (dvīpa) in the Yamunā, to the sage Parāśara and Satyavatī.','<b>The arranger.</b> He is called <b>Vyāsa</b>, “the arranger”, for dividing the one Veda into four (Ṛg, Yajur, Sāma, Atharva) and teaching each to a disciple.','<b>The author.</b> Tradition credits him with the Mahābhārata (including the Gītā), the eighteen Purāṇas and the Brahma Sūtra. He also appears in the Mahābhārata as grandfather of the Kauravas and Pāṇḍavas.','<b>Cirañjīvin.</b> He is counted among the cirañjīvins, those said to live through the ages.'],[('z','One man wrote all that?'),('b','Tradition says so; scholars see many hands across centuries under his name. Either way, “Vyāsa” stands for the tradition of passing knowledge on.')],'Vyāsa: <b>the arranger of the Veda</b>, the author of the epic.'),
 story('ganesha','VYĀSA AND GAṆEŚA','How the Mahābhārata was written down',strip('Three panels: Vyāsa asking Gaṇeśa to write; Gaṇeśa’s condition; Gaṇeśa writing with his broken tusk',[panel([(VY(),.8),('<circle cy="-30" r="20" fill="#f4a6b8" stroke="#111" stroke-width="2"/>',1)],'#fff3cf',140),panel([('<circle cy="-30" r="20" fill="#f4a6b8" stroke="#111" stroke-width="2"/>',1.2)],'#cfe0b8',140),panel([(book(),1.4),('<path d="M0 0 l12 -30" stroke="#fff" stroke-width="6"/>',1)],'#dfe9f6',140)],['a scribe is needed','“don’t stop dictating”','the broken tusk']),'A well-loved story, found in some versions of the Mahābhārata.',['Vyāsa had the whole Mahābhārata in his mind and needed a scribe fast enough to write it.','He asked Gaṇeśa. Gaṇeśa agreed on one condition: Vyāsa must never pause in his dictation.','Vyāsa added his own condition: Gaṇeśa must understand every verse before writing it.','Whenever Vyāsa needed time, he composed a very difficult verse; while Gaṇeśa worked it out, Vyāsa composed the next.','When his pen broke, Gaṇeśa broke off his own tusk and kept writing. Our <a href="/ganesha/stories/broken-tusk/">Gaṇeśa: The Broken Tusk</a> tells it fully.'],[('z','So the hard verses were a trick to buy time?'),('b','So the story says. A teacher and a student, each testing the other. Very Guru Pūrṇimā.')],'Vyāsa dictates, <b>Gaṇeśa writes with his tusk</b>.'),
 reading('day','HOW THE DAY IS KEPT','Honouring teachers',svg(560,170,'A student bowing at a teacher’s feet and offering flowers and fruit',g(200,160,1,sage('#e0a800'))+g(320,160,1,person('#1d6fb8',seat=True))+g(270,140,.8,pot('#f08a24'))),['<b>Guru pūjā.</b> Disciples worship their teacher, offering flowers, fruit, clothes and a gift (dakṣiṇā), and touch the teacher’s feet.','<b>Vyāsa pūjā.</b> In monasteries (maṭhas) the head of the order performs worship of Vyāsa and the line of teachers; see '+L(2,'Part 3')+'.','<b>Students and music.</b> Schools of music and dance, and students of every kind, honour their teachers on this day.','<b>Other traditions.</b> Buddhists remember the Buddha’s first sermon at Sārnāth on this full moon; Jains remember Mahāvīra’s first disciple.'],[('z','Can I honour a school teacher too?'),('b','Of course. Anyone who has taught you something true is your guru for that.')],'Flowers at the teacher’s feet: <b>Guru Pūrṇimā</b>.'),
 end(i,['<b>Day.</b> Full moon of Āṣāḍha: Guru Pūrṇimā, Vyāsa Pūrṇimā.','<b>Vyāsa.</b> Kṛṣṇa Dvaipāyana, arranger of the Veda.','<b>Works.</b> Mahābhārata, Purāṇas, Brahma Sūtra (by tradition).','<b>Story.</b> Gaṇeśa wrote the epic as Vyāsa dictated.','<b>Practice.</b> Honour the teacher.'],'Part 2 asks what a guru is, with the famous “gurur brahmā” verses.','Vyāsa Pūrṇimā'),
 sources([('Vyāsa:','Wikipedia, “Vyasa”, “Guru Purnima”; Mahābhārata, Ādi Parva (birth of Vyāsa; Gaṇeśa episode in some recensions).')],'authorship of the Purāṇas and Mahābhārata (traditional vs scholarly); the Gaṇeśa episode (absent from the critical edition).','Traditions given as tradition.')]
build(i,'PART 1 OF 3 · VYĀSA · THE ARRANGER',COV,'The sage who arranged the Veda','Who <b>Vyāsa</b> was, how <b>Gaṇeśa</b> wrote down his epic, and how the day is kept.','Guru Pūrṇimā as Vyāsa Pūrṇimā: who Vyāsa (Kṛṣṇa Dvaipāyana) was, the arranger of the Veda and author of the Mahābhārata, the story of Gaṇeśa as his scribe, and how teachers are honoured. Part 1 of the illustrated Guru Pūrṇimā series.',pp)
i=1
COV=covart('Dakṣiṇāmūrti seated under a banyan tree in silence, with four old sages at his feet listening',g(220,196,2.2,tree())+g(220,190,1,shiva())+''.join(g(x,196,.7,sage('#e0a800')) for x in (90,140,300,350)))
M=[('THE GURU IS GOD','The guru is Brahmā, the guru is Viṣṇu, the guru is the god Maheśvara; the guru is truly the supreme Brahman. To that glorious guru, salutations.',[('guruḥ','the teacher'),('brahmā viṣṇuḥ maheśvaraḥ','creator, preserver, transformer'),('param brahma','the supreme reality'),('tasmai śrī-gurave namaḥ','to that glorious guru, salutations')],'<b>Three in one.</b> The verse names the three great gods and then goes beyond them: the guru is the supreme reality itself, because the guru reveals it.'),
 ('THE EYE OPENED','To the one who, with the salve-stick of knowledge, opened the eyes of one blinded by the darkness of ignorance: to that glorious guru, salutations.',[('ajñāna-timira-andhasya','of one blinded by the darkness of ignorance'),('jñāna-añjana-śalākayā','with the applicator of the salve of knowledge'),('cakṣuḥ unmīlitam','the eye was opened'),('yena','by whom')],'<b>An eye doctor’s image.</b> In old India a physician applied a medicated salve (añjana) with a thin stick to clear the eyes. The guru does the same for the mind.'),
 ('THE WHOLE SHOWN','To the one who showed me that state which pervades all that moves and does not move, in the form of an unbroken whole: to that glorious guru, salutations.',[('akhaṇḍa-maṇḍala-ākāram','in the form of an unbroken whole'),('vyāptam','pervading'),('cara-acaram','the moving and unmoving'),('tat-padam','that state, that reality'),('darśitam','shown')],'<b>“That” shown.</b> <i>Tat</i>, “that”, is the Upaniṣadic word for the highest reality, as in “tat tvam asi”. The guru’s gift is to show it, not just to describe it.')]
pp=[foreword(i,['What is a guru? Literally “heavy” or “weighty”, a guru is one who carries real knowledge, and above all the teacher who leads a student to the truth. A popular explanation reads <i>gu</i> as darkness and <i>ru</i> as removing it.','This part reads the three most famous guru verses, from the <b>Guru Gītā</b>, and meets <b>Dakṣiṇāmūrti</b>, Śiva as the silent teacher.'],[('z','Is every teacher a guru?'),('b','In ordinary speech, yes. In the deep sense, the guru is the one who opens your eyes to the highest truth.')]),
 glance([('Word','Guru: “weighty”; popularly gu (darkness) + ru (remover)'),('Verses','Guru Gītā 58–60: “gururbrahmā…”, “ajñānatimirāndhasya…”, “akhaṇḍamaṇḍalākāram…”'),('Source','Guru Gītā, presented as from the Skanda Purāṇa, a dialogue of Śiva and Pārvatī'),('Teacher of teachers','Dakṣiṇāmūrti, Śiva facing south, teaching in silence'),('Line','Guru-paramparā: the chain of teachers')],svg(560,140,'A lamp passing its flame to another lamp, and another',''.join(g(140+k*140,110,1.4,lamp()) for k in range(3))+'<path d="M160 70 q60 -30 120 0 M300 70 q60 -30 120 0" stroke="#e0a800" stroke-width="2" fill="none" stroke-dasharray="4 4"/>'))]
for k,(t,mean,words,ins) in enumerate(M):
    pp.append(verse(f'v{k+1}',f'GURU GĪTĀ {58+k}',t,GV[2*k:2*k+2],svg(220,160,'A teacher seated with a lamp',g(110,150,1.1,sage('#e0a800'))+g(170,150,.9,lamp()),cls=''),mean,words,ins,None,['The guru reveals the supreme.','Knowledge, applied like salve, opens the eye.','The guru shows the whole.'][k],'Text: sanskritdocuments.org, Guru Gītā (doc_giitaa/gurugita), verses 58–60; ITRANS converted to IAST.'))
pp+=[reading('dakshinamurti','DAKṢIṆĀMŪRTI','The silent teacher',svg(560,180,'Śiva seated under a banyan facing south, a young teacher among old disciples, his hand in the gesture of knowledge',g(280,175,2.3,tree())+g(280,170,1.1,shiva())+''.join(g(x,175,.7,sage('#e0a800')) for x in (120,170,390,440))),['<b>Facing south.</b> <b>Dakṣiṇāmūrti</b>, “the one facing south”, is Śiva as the supreme teacher, seated under a banyan tree. His image is found on the south wall of almost every Śiva temple in the south.','<b>Young teacher, old students.</b> A famous verse marvels: under the banyan sits a young guru with aged disciples; the teaching is silence, and yet their doubts are cut away.','<b>The gesture.</b> His hand forms the <b>cin-mudrā</b>, index finger touching thumb, the sign of the individual self joined to the supreme.','<b>Thursday.</b> In the south he is especially worshipped on Thursdays (guruvāra).'],[('z','Teaching in silence?'),('b','The highest truth is beyond words. In his presence, the tradition says, students simply understood.')],'Śiva as the teacher who <b>teaches in silence</b>.'),
 reading('parampara','THE LINE OF TEACHERS','Guru-paramparā',svg(560,150,'A chain of seated teachers from left to right, each passing a lamp',''.join(g(60+k*88,130,.8,sage(['#e0a800','#ff8c1a','#c0392b','#2a9d6f','#1d6fb8','#7a3fa0'][k])) for k in range(6))),['<b>A chain.</b> Every tradition counts its teachers in a line (<b>paramparā</b>), from the original teacher down to one’s own. Knowledge is trusted because of the line it came through.','<b>Śaṅkara’s line.</b> The Advaita line begins with Nārāyaṇa, Brahmā, Vasiṣṭha, Śakti, Parāśara, Vyāsa and Śuka, then Gauḍapāda, Govinda Bhagavatpāda and Śaṅkara. Other traditions (Rāmānuja’s, Madhva’s) have their own.','<b>Honouring the line.</b> On Guru Pūrṇimā, not only the living teacher but the whole line is worshipped.','<b>Your own line.</b> Parents, school teachers, music teachers: everyone who taught us is in our own small paramparā.'],[('z','Vyāsa is in Śaṅkara’s line?'),('b','Right in the middle: Parāśara’s son, Śuka’s father. That is why his day is the teachers’ day.')],'A lamp lit from a lamp: <b>the line of teachers</b>.'),
 end(i,['<b>Word.</b> Guru: weighty; the remover of darkness.','<b>58.</b> The guru is Brahmā, Viṣṇu, Maheśvara and the supreme.','<b>59.</b> The guru opens the eye blinded by ignorance.','<b>Dakṣiṇāmūrti.</b> Śiva, the silent teacher under the banyan.','<b>Paramparā.</b> The line of teachers, Vyāsa at its heart.'],'Part 3: Cāturmāsya, the four-month retreat of the ascetics, which begins at this season.','The guru'),
 sources([('Text:','sanskritdocuments.org, Guru Gītā, verses 58–60. Wikipedia, “Guru Gita”, “Dakshinamurti”, “Guru–shishya tradition”.')],'the Guru Gītā’s place in the Skanda Purāṇa (absent from many printed editions); the gu/ru etymology (popular).','Verse numbers as in the sanskritdocuments edition.')]
build(i,'PART 2 OF 3 · GURU GĪTĀ · DAKṢIṆĀMŪRTI',COV,'The silent teacher under the banyan','What a <b>guru</b> is, the three famous verses of the <b>Guru Gītā</b> word by word, <b>Dakṣiṇāmūrti</b>, and the <b>line of teachers</b>.','The guru in Hindu tradition: Guru Gītā verses 58–60 (“gururbrahmā…”) in IAST with meanings, Dakṣiṇāmūrti the silent teacher, and the guru-paramparā. Part 2 of the illustrated Guru Pūrṇimā series.',pp)
i=2
COV=covart('A sannyāsin in ochre with a staff seated in a monastery during heavy rain, disciples around',''.join(f'<path d="M{x} 10 v30" stroke="#8fb8de" stroke-width="2"/>' for x in range(20,440,24))+g(220,196,1.3,sage('#ff8c1a'))+g(250,150,1,'<path d="M0 50 v-110" stroke="#8a5a2a" stroke-width="3"/>')+''.join(g(x,196,.7,person('#f4f1ea',seat=True)) for x in (100,340)))
pp=[foreword(i,['The rains are coming. For sannyāsins, the monks of the Hindu orders, Guru Pūrṇimā marks the start of <b>Cāturmāsya</b>, “the four months”, when they stop wandering and stay in one place through the monsoon.','On this day the heads of the great maṭhas, such as Śṛṅgeri in Karnataka, perform <b>Vyāsa Pūjā</b> and take the Cāturmāsya vow.'],[('z','Why stop travelling in the rains?'),('b','In the old days, roads became rivers. And travelling would trample the life that bursts out of the wet earth.')]),
 glance([('Name','Cāturmāsya, “the four months”'),('For ascetics','Begins around Āṣāḍha Pūrṇimā (Vyāsa Pūjā)'),('For householders','Often from Devaśayanī Ekādaśī to Prabodhinī Ekādaśī'),('Practice','Staying in one place; teaching; extra vows and food restrictions'),('Ends','In Kārtika (Prabodhinī Ekādaśī) or with the full moon of Bhādrapada for some orders (two lunar fortnights counted as a month)')],svg(560,140,'Four rain clouds, one for each month',''.join(g(80+k*130,80,1,'<path d="M-40 0 q0 -20 20 -20 q10 -20 30 -10 q20 -10 30 10 q10 10 0 20z" fill="#dfe9f6" stroke="#111" stroke-width="2"/>')+''.join(f'<path d="M{80+k*130+x} 90 v20" stroke="#5a8ac0" stroke-width="2"/>' for x in (-20,0,20)) for k in range(4)))),
 reading('vyasapuja','VYĀSA PŪJĀ','In the maṭhas',svg(560,170,'A monastery head worshipping a row of seated teachers’ images with lamps',ground(560,170,150,'#e9d6c0')+''.join(g(160+k*60,140,.6,sage(['#e0a800','#ff8c1a','#c0392b','#2a9d6f','#1d6fb8'][k])) for k in range(5))+g(450,150,1,sage('#ff8c1a'))+g(400,130,.9,lamp())),['<b>Worshipping the line.</b> On Āṣāḍha Pūrṇimā the head of a monastic order performs <b>Vyāsa Pūjā</b>: worship of Vyāsa, Kṛṣṇa, Śaṅkara (for Advaita orders) and the whole line of teachers, represented in groups.','<b>The vow.</b> Then the sannyāsin takes the Cāturmāsya saṅkalpa, a vow to stay in that place for the season.','<b>Śṛṅgeri.</b> At the Śṛṅgeri Śāradā Pīṭham in Karnataka, the Jagadguru’s Vyāsa Pūjā and Cāturmāsya are major events for devotees, as are those of the Udupi and other maṭhas.','<b>Devotees.</b> Devotees come to receive blessings and listen to teaching through the months.'],[('z','Where does the monk stay?'),('b','Wherever he has taken the vow: his own maṭha, or a town that invited him. That town is blessed with four months of teaching.')],'Vyāsa Pūjā: <b>the line of teachers worshipped, the vow taken</b>.'),
 reading('householders','FOR HOUSEHOLDERS','Vows of the four months',svg(560,160,'Four plates with different foods crossed out, one for each month',''.join(g(90+k*125,120,1,'<ellipse rx="40" ry="12" fill="#e8c06a" stroke="#111"/>')+f'<path d="{"M"+str(60+k*125)+" 100 L"+str(120+k*125)+" 140"}" stroke="#c0392b" stroke-width="4"/>' for k in range(4))+''.join(lab(90+k*125,155,t) for k,t in enumerate(['leafy greens','curd','milk','some pulses']))),['<b>Same season.</b> Householders keep their own Cāturmāsya, usually from <a href="/festivals/ekadashi/devashayani/">Devaśayanī Ekādaśī</a>, when Viṣṇu sleeps, to Prabodhinī, when he wakes.','<b>Food vows.</b> A common pattern gives up leafy vegetables in the first month, curd in the second, milk in the third, and certain pulses in the fourth. Many families keep their own variations.','<b>Other vows.</b> Reading a scripture daily, a fixed japa, a lamp at the tulasī, or giving up a habit.','<b>Practical roots.</b> Many note that the food rules suit the monsoon’s health risks; the tradition’s reason is devotion.'],[('z','Four months without curd?'),('b','One month, in that pattern. And it’s a vow you choose, not a law.')],'Four months, <b>one small vow at a time</b>.'),
 reading('meaning','THE MEANING OF THE RETREAT','Stillness in the rains',svg(560,150,'A seated meditator under a roof while rain falls outside',''.join(f'<path d="M{x} 10 v30" stroke="#8fb8de" stroke-width="2"/>' for x in range(20,560,24))+g(280,140,1.2,'<path d="M-80 -80 h160 l-20 -20 h-120z" fill="#a8553a" stroke="#111" stroke-width="2"/>')+g(280,140,1.2,person('#ff8c1a',seat=True))),['<b>Ahiṃsā.</b> The old reason is non-violence: in the rains, insects and small life fill the earth, and a wandering monk would trample them.','<b>Teaching.</b> A monk staying in one place can teach a community deeply, as Buddhist monks do in their own rainy-season retreat (vassa).','<b>Inner retreat.</b> For everyone, the season invites turning inward: less travel, more study and prayer.','<b>Closing.</b> The retreat ends with Viṣṇu’s waking in Kārtika; see our <a href="/festivals/kartika/prabodhini-tulasi-vivaha/">Kārtika series</a>.'],[('z','So the rainy season is a kind of school term?'),('b','A good way to put it: the guru stays, the students gather, and the rain keeps everyone home.')],'Stillness in the rains: <b>the teacher stays, the students gather</b>.'),
 end(i,['<b>Cāturmāsya.</b> The four-month rainy-season retreat.','<b>Begins.</b> With Vyāsa Pūjā on Guru Pūrṇimā (for ascetics).','<b>Maṭhas.</b> Śṛṅgeri, Udupi and others host the season’s teaching.','<b>Householders.</b> Devaśayanī to Prabodhinī; food and other vows.','<b>Meaning.</b> Non-violence, teaching, inner retreat.'],'That completes the Guru Pūrṇimā series. See also our <a href="/festivals/ekadashi/">Ekādaśī series</a> for Devaśayanī and Prabodhinī.','Cāturmāsya begins'),
 sources([('Practice:','Wikipedia, “Chaturmasya”, “Guru Purnima”, “Sringeri Sharada Peetham”.')],'the food-vow pattern (varies by family and sampradāya); exact start and end for different orders.','Customs given in general form.')]
build(i,'PART 3 OF 3 · THE FOUR MONTHS · VYĀSA PŪJĀ',COV,'The monk who stays for the rains','<b>Vyāsa Pūjā</b> in the maṭhas, the <b>householders’ vows</b>, and the <b>meaning of the retreat</b>.','Cāturmāsya, the four-month rainy-season retreat beginning at Guru Pūrṇimā: Vyāsa Pūjā in the maṭhas such as Śṛṅgeri, householders’ vows from Devaśayanī to Prabodhinī, and its meaning. Part 3 of the illustrated Guru Pūrṇimā series.',pp)
# ================= AKṢAYA TṚTĪYĀ
run_series('/festivals/akshaya-tritiya/',[('','Akṣaya Tṛtīyā','The Day That Never Diminishes')],'navy','Akṣaya Tṛtīyā','Lord','Akṣaya Tṛtīyā','outx/akshaya-tritiya/')
i=0
COV=covart('A bowl overflowing with rice that never empties, Paraśurāma with his axe, the river Gaṅgā descending from the sky, and Kṛṣṇa embracing his poor friend Sudāmā',g(110,196,1.2,pot('#e0a800'))+g(110,150,1.2,'<path d="M-14 0 q14 -16 28 0" fill="#fff"/>')+g(200,196,1,person('#1d6fb8'))+g(230,140,.8,'<path d="M0 40 v-60" stroke="#8a5a2a" stroke-width="3"/><path d="M0 -20 q14 -6 14 10 h-14z" fill="#9aa"/>')+'<path d="M330 10 q-20 80 0 186" stroke="#8fb8de" stroke-width="16" fill="none"/>'+g(400,196,1,person('#5a8ad0'))+g(420,196,.9,person('#8a6a4a')))
pp=[foreword(i,['On the third day of the bright half of Vaiśākha falls <b>Akṣaya Tṛtīyā</b>, “the third day that never diminishes”. Whatever good is begun or given on this day, tradition says, does not decay.','It gathers many stories: Paraśurāma’s birth, the Gaṅgā’s descent, the inexhaustible bowl, Kṛṣṇa and Sudāmā, the opening of Badrīnāth. In Karnataka it is also <b>Basava Jayantī</b>. This guide tells them, and says frankly where modern custom has added to tradition.'],[('z','Isn’t it just for buying gold?'),('b','That is the newest layer. Underneath are much older stories about giving.')]),
 glance([('When','Bright third (tṛtīyā) of Vaiśākha (April–May)'),('Name','Akṣaya: “undecaying, inexhaustible”'),('Stories','Paraśurāma Jayantī; the Gaṅgā’s descent; the akṣaya pātra; Sudāmā'),('Temples','Badrīnāth opens; Simhācalam’s sandalwood darśan'),('Karnataka','Basava Jayantī'),('Customs','Charity, new beginnings, (recently) buying gold')],svg(560,140,'A bowl overflowing that never empties',g(280,130,2,pot('#e0a800'))+g(280,90,2,'<path d="M-14 0 q14 -16 28 0" fill="#fff"/>'))),
 reading('akshaya','THE NAME','What never diminishes',svg(560,160,'A lamp whose flame lights many other lamps without growing smaller',''.join(g(100+k*90,130,1.2,lamp()) for k in range(5))),['<b>Akṣaya.</b> <i>Kṣaya</i> is decay or loss; <b>akṣaya</b> is what does not decay. The day is held to make good deeds, gifts and prayers “inexhaustible” in their fruit.','<b>A self-auspicious day.</b> It is one of the few days counted auspicious all day long, so no particular hour needs to be chosen for new beginnings.','<b>Giving.</b> The texts that praise it speak above all of giving: water pots, food, umbrellas, sandals and fans in the coming heat.','<b>Tretā Yuga.</b> Some traditions say the Tretā age began on this day.'],[('z','So it’s a lucky day?'),('b','More a fruitful day: what you sow, especially in giving, keeps growing.')],'Akṣaya: <b>good that never runs out</b>.'),
 story('parashurama','PARAŚURĀMA JAYANTĪ','Viṣṇu’s sixth avatāra',strip('Three panels: the sage Jamadagni and Reṇukā with a baby; young Paraśurāma receiving an axe from Śiva; Paraśurāma with his axe',[panel([(sage('#e0a800'),.7),(person('#c0392b'),.7)],'#fff3cf',140),panel([(shiva(),.7),(person('#1d6fb8'),.6)],'#dfe9f6',140),panel([(person('#1d6fb8'),.9),('<path d="M0 40 v-80" stroke="#8a5a2a" stroke-width="3"/><path d="M0 -40 q16 -8 16 12 h-16z" fill="#9aa" stroke="#111"/>',1)],'#cfe0b8',140)],['born to Jamadagni','the axe from Śiva','Paraśurāma']),'Many celebrate Akṣaya Tṛtīyā as the birthday of Paraśurāma.',['<b>Paraśurāma</b>, “Rāma with the axe”, was born to the sage Jamadagni and Reṇukā.','He pleased Śiva by penance and received the divine axe (paraśu).','When the arrogant king Kārtavīrya’s sons killed his father, he fought the corrupt warrior kings again and again.','He later gave away the earth he had won and retired to the Western Ghats; tradition says he reclaimed the coast of Kerala and Karnataka from the sea.','He is a cirañjīvin, said to live on; he teaches Bhīṣma, Droṇa and Karṇa in the Mahābhārata. Our <a href="/vishnu/dashavatara/">Daśāvatāra series</a> tells his story fully.'],[('z','He made the west coast?'),('b','So the coastal tradition says: he threw his axe into the sea and the land rose. Gokarṇa and Udupi remember him.')],'Akṣaya Tṛtīyā: <b>Paraśurāma’s birthday</b>.'),
 cards('stories','OTHER STORIES OF THE DAY','Gaṅgā, the bowl, Sudāmā and Kubera',svg(560,170,'Four small scenes: the Gaṅgā falling from the sky, a bowl of food, two friends embracing, and a treasure chest',g(80,160,1,'<path d="M0 -150 q-20 70 0 150" stroke="#8fb8de" stroke-width="16" fill="none"/>')+g(210,150,1.4,pot('#e0a800'))+g(340,160,.9,person('#5a8ad0'))+g(370,160,.9,person('#8a6a4a'))+g(480,150,1,'<rect x="-30" y="-30" width="60" height="30" fill="#a8553a" stroke="#111" stroke-width="2"/><circle cy="-34" r="8" fill="#e0a800"/>')),[('🌊','The Gaṅgā descends','Some traditions say the Gaṅgā came down to earth on this day, brought by Bhagīratha’s penance.'),('🍚','The akṣaya pātra','In the Mahābhārata the exiled Pāṇḍavas received an inexhaustible vessel from the Sun, which fed all their guests each day until Draupadī had eaten. Popular tradition places the gift on this day.'),('🤝','Sudāmā','Kṛṣṇa’s poor childhood friend Sudāmā brought him a handful of flattened rice; Kṛṣṇa received it with love and Sudāmā returned home to find his hut a palace. Many tell this story today.'),('💰','Kubera and Lakṣmī','Some traditions say Kubera received his wealth by worshipping Śiva and Lakṣmī on this day, which is part of how the day became tied to wealth.')],[('z','So many stories, all about giving?'),('b','Look closely: the inexhaustible bowl, a handful of rice, the river given to earth. Every one is about a gift that never runs out.')],'A river, a bowl, a handful of rice: <b>gifts that never run out</b>.'),
 reading('temples','THE DAY IN TEMPLES','Badrīnāth and Siṃhācalam',svg(560,170,'A Himalayan temple with its doors opening on the left, and a deity covered in sandalwood paste on the right',g(150,160,1.2,mountain())+g(150,160,.7,'<path d="M-30 0 v-60 h60 v60z" fill="#c0392b" stroke="#111" stroke-width="2"/>')+g(420,160,1.2,'<path d="M-30 0 q-4 -60 30 -70 q34 10 30 70z" fill="#f3e3c3" stroke="#111" stroke-width="2"/>')+lab(150,176,'Badrīnāth opens')+lab(420,176,'Siṃhācalam’s nija rūpa')),['<b>Badrīnāth.</b> The great Viṣṇu shrine in the Himālaya, closed through winter, traditionally reopens around this time; the dates are announced each year. See our <a href="/temples-of-india/char-dham/">Char Dhām series</a>.','<b>Siṃhācalam.</b> At the Narasiṃha temple of Siṃhācalam in Andhra, the deity is covered in sandalwood paste all year; on Akṣaya Tṛtīyā the paste is removed for the <b>nija-rūpa darśan</b>, the true form, then reapplied.','<b>Purī.</b> At Purī, construction of the chariots for the Ratha Yātrā begins around this day.','<b>Everywhere.</b> Temples hold special worship, and many begin new festivals.'],[('z','The deity is covered in sandalwood all year?'),('b','At Siṃhācalam, yes, to cool the fierce Narasiṃha. Seeing him uncovered is the great event of the day.')],'Doors open, sandalwood removed: <b>temples on Akṣaya Tṛtīyā</b>.'),
 reading('basava','BASAVA JAYANTĪ','Karnataka’s own',svg(560,160,'A twelfth-century saint holding palm-leaf verses with a liṅga worn on a cord',g(280,150,1.3,person('#e0a800'))+g(280,95,.6,'<path d="M-6 0 v-10 q6 -6 12 0 v10z" fill="#3a3a40"/>')+g(400,140,1,book())),['<b>Basavaṇṇa.</b> In Karnataka the day is also <b>Basava Jayantī</b>, birthday of <b>Basavaṇṇa</b> (12th century), the poet-saint and statesman of Kalyāṇa who founded the Vīraśaiva-Liṅgāyata movement.','<b>His teaching.</b> Through his short Kannada poems (vacanas) he taught devotion to Śiva, honest work (kāyaka) and the equality of all, rejecting caste and empty ritual.','<b>Anubhava Maṇṭapa.</b> His hall of experience gathered saints of every background, men and women.','<b>The day.</b> Liṅgāyat communities celebrate with processions, readings of vacanas and community meals.'],[('z','A saint who wrote short poems?'),('b','Hundreds of vacanas, still sung. “Work is worship” (kāyakavē kailāsa) is his most famous line.')],'In Karnataka: <b>Basavaṇṇa’s birthday</b>.'),
 reading('gold','THE GOLD QUESTION','Old tradition and new custom',svg(560,150,'A gold coin and a plate of food side by side, with the food plate larger',g(180,120,1.4,'<circle r="26" fill="#e0a800" stroke="#111" stroke-width="2"/>')+g(380,120,1.6,'<ellipse rx="50" ry="14" fill="#5a8a3a" stroke="#111"/>'+''.join(f'<circle cx="{x}" cy="-8" r="8" fill="#fff"/>' for x in (-20,0,20)))),['<b>Frankly.</b> Buying gold on Akṣaya Tṛtīyā is now very popular and heavily advertised. It is a recent custom; the older texts praise <b>giving</b>, not buying.','<b>The logic.</b> If what is begun today never diminishes, people reasoned, so will wealth bought today. Kubera’s story helped.','<b>Tradition’s own emphasis.</b> Gifts of water, food, clothes and shelter in the summer heat, worship, and good beginnings.','<b>A balance.</b> There is nothing wrong with marking the day with a purchase; but by the tradition’s own logic, a gift to someone in need is the truer Akṣaya act.'],[('z','So should I buy gold or not?'),('b','That’s your call. The tradition’s answer is: give something. That is what never diminishes.')],'The tradition says <b>give</b>; the market says buy.'),
 end(i,['<b>Name.</b> Akṣaya Tṛtīyā: the third that never diminishes.','<b>Stories.</b> Paraśurāma’s birth, the Gaṅgā, the akṣaya pātra, Sudāmā, Kubera.','<b>Temples.</b> Badrīnāth reopens; Siṃhācalam’s sandalwood removed.','<b>Karnataka.</b> Basava Jayantī.','<b>Spirit.</b> Giving, not just buying.'],'See also our <a href="/festivals/">festival calendar</a>; next in season are the Ekādaśīs of Vaiśākha (<a href="/festivals/ekadashi/varuthini/">Varūthinī</a> and <a href="/festivals/ekadashi/mohini/">Mohinī</a>).','Akṣaya Tṛtīyā'),
 sources([('Day:','Wikipedia, “Akshaya Tritiya”, “Parashurama”, “Akshaya Patra”, “Sudama”, “Simhachalam Temple”, “Basava”.')],'which events tradition places on this day (lists vary and some are recent); the antiquity of the gold-buying custom.','No dates or timings given.')]
build(i,'THE THIRD DAY · GIVING · PARAŚURĀMA · BASAVA',COV,'Gifts that never run out','<b>What akṣaya means</b>, <b>Paraśurāma’s birth</b>, the stories of the day, the <b>temples</b>, <b>Basava Jayantī</b>, and a frank word on gold.','Akṣaya Tṛtīyā explained: the meaning of akṣaya, Paraśurāma Jayantī, the Gaṅgā’s descent, the akṣaya pātra, Sudāmā and Kubera, Badrīnāth and Siṃhācalam, Basava Jayantī in Karnataka, and the modern gold custom.',pp)
# ================= ŚRĀVAṆA PŪRṆIMĀ
run_series('/festivals/shravana-purnima/',[('upakarma','Upākarma','Renewing the Thread and the Veda'),('raksha-bandhan','Rakṣā Bandhan','The Thread of Protection')],'navy','Śrāvaṇa Pūrṇimā','Lord','Śrāvaṇa Pūrṇimā','outx/shravana-purnima/')
i=0
HAY='<circle cy="-56" r="13" fill="#fff"/><path d="M-8 -62 q8 -16 20 -6 q-4 10 -12 12" fill="#fff" stroke="#111" stroke-width="2"/>'
COV=covart('Men seated by a river changing their sacred thread, a priest reciting, and a white horse-headed Hayagrīva with a book above',river(440,160)+''.join(g(x,190,.9,person('#f4f1ea',seat=True)) for x in (90,150,210))+g(150,150,.9,sacred_thread())+g(340,170,1,vishnu().replace('<circle cy="-56" r="13" fill="#5a8ad0"/>',HAY)))
pp=[foreword(i,['On the full moon of Śrāvaṇa, two very different observances fall on the same day. One is <b>Upākarma</b>: men who wear the sacred thread change it for a new one and ceremonially begin the year’s study of the Veda. The other is <b>Rakṣā Bandhan</b> ('+pages.link(1,'Part 2')+').','In Tamil Nadu Upākarma is <b>Āvaṇi Aviṭṭam</b>; the same day is also <b>Hayagrīva Jayantī</b>, birthday of Viṣṇu’s horse-headed form, Lord of learning.'],[('z','Why change a thread every year?'),('b','To renew a vow. The thread stands for a commitment to study and discipline; once a year it is made new.')]),
 glance([('Name','Upākarma; Āvaṇi Aviṭṭam (Tamil); Janivāra Huṇṇime (Kannada)'),('When','Śrāvaṇa Pūrṇimā (some Vedic schools on other days in the month)'),('Who','Those who wear the yajñopavīta (sacred thread)'),('Rites','Bath, atonement (prāyaścitta), new thread, ṛṣi-tarpaṇa, starting Veda study'),('Next day','Gāyatrī japa (1008 times in many traditions)'),('Also','Hayagrīva Jayantī')],svg(560,140,'A sacred thread drawn in a loop',g(280,100,1.8,sacred_thread()))),
 reading('thread','THE SACRED THREAD','Yajñopavīta',svg(560,170,'A person wearing a sacred thread over the left shoulder, with the three strands shown',g(280,160,1.6,person('#f4f1ea'))+g(280,120,1.2,sacred_thread())+lab(430,90,'three strands, a knot')),['<b>The thread.</b> The <b>yajñopavīta</b> (Kannada <i>janivāra</i>, Tamil <i>pūṇūl</i>) is a cord of three strands worn from the left shoulder across the body, given at the upanayana, the ceremony that begins Vedic study.','<b>Its meaning.</b> The three strands are read in many ways: the three debts (to gods, sages and ancestors), the three guṇas, or the three goddesses of speech. The knot is the brahma-granthi.','<b>Who wears it.</b> Traditionally worn by boys and men of communities that perform upanayana; practice today varies.','<b>Renewing.</b> Worn threads are changed whenever needed, and always at Upākarma.'],[('z','Three strands, many meanings?'),('b','The tradition loves layered meanings. The one everyone agrees on: a promise to learn and to live with discipline.')],'Three strands, <b>a promise renewed</b>.'),
 story('rite','THE UPĀKARMA RITE','How the day runs',strip('Three panels: a ritual bath; offering water to the sages; reciting the Veda',[panel([(river(144,100),1),(person('#f4f1ea'),.8)],'#dfe9f6',None),panel([(person('#f4f1ea'),.8),(pot('#c9a24a'),.8)],'#fff3cf',140),panel([(book(),1.4),(sage('#e0a800'),.7)],'#cfe0b8',140)],['bath and atonement','ṛṣi-tarpaṇa','Veda begun again']),'The rite varies by Veda and school; this is the common shape.',['<b>Bath and atonement.</b> A holy bath, and a prāyaścitta, an atonement for lapses of the year, especially in study and daily rites.','<b>New thread.</b> The new yajñopavīta is worn with mantras, and the old one set aside.','<b>Ṛṣi-tarpaṇa.</b> Water is offered to the ṛṣis, the seers through whom the Veda came, in thanks.','<b>Starting again.</b> The Veda is ceremonially begun afresh, often with the opening portions of one’s own branch.','<b>Gāyatrī japa.</b> The next day many recite the Gāyatrī mantra 1008 times; see our <a href="/devi/gayatri-mantra/">Gāyatrī article</a>.'],[('z','Who are the ṛṣis thanked?'),('b','The seers in whom the Vedic hymns arose: Vasiṣṭha, Viśvāmitra, Atri and the rest. Without them, no Veda.')],'Atone, renew, thank the seers, <b>begin again</b>.'),
 reading('hayagriva','HAYAGRĪVA JAYANTĪ','The Lord of learning',svg(560,170,'Viṣṇu with a white horse’s head seated with a book and rosary',g(280,165,1.3,devi(skin='#fff',sari='#e0a800',items=('book','rosary','conch','discus'),halo='#fff3b0',third_eye=False,seat=True)).replace('<circle cy="-56" r="13" fill="#fff"/>',HAY)),['<b>The horse-headed Viṣṇu.</b> <b>Hayagrīva</b> is Viṣṇu with a horse’s head, white and shining, honoured as the Lord of knowledge.','<b>His story.</b> The Purāṇas tell that demons stole the Vedas from Brahmā; Viṣṇu took the horse-headed form, recovered them and restored them.','<b>Upākarma’s patron.</b> So he is worshipped on the day the Veda is begun afresh. In the Śrīvaiṣṇava tradition he is especially loved, and Vedānta Deśika’s Hayagrīva Stotra is widely recited.','<b>For students.</b> Students pray to him before study and exams, as to Sarasvatī.'],[('z','A horse-headed god for students?'),('b','He recovered the Veda itself. If anyone can help with your exams…')],'Hayagrīva: <b>Viṣṇu who restored the Veda</b>.'),
 end(i,['<b>Upākarma.</b> The sacred thread renewed on Śrāvaṇa Pūrṇimā.','<b>Thread.</b> Yajñopavīta: three strands, a promise to study.','<b>Rite.</b> Atonement, new thread, ṛṣi-tarpaṇa, Veda begun again.','<b>Next day.</b> Gāyatrī japa.','<b>Hayagrīva.</b> Viṣṇu who restored the Veda.'],'Part 2 is the other festival of the same full moon: Rakṣā Bandhan.','Upākarma'),
 sources([('Rite:','Wikipedia, “Upakarma”, “Avani Avittam”, “Yajnopavita”, “Hayagriva”.')],'days for different Vedic schools (Sāma-vedins often keep it on another day); interpretations of the three strands.','Described in general terms; follow your family’s Vedic tradition.')]
build(i,'PART 1 OF 2 · THE THREAD · THE VEDA · HAYAGRĪVA',COV,'A thread renewed, the Veda begun again','The <b>sacred thread</b>, the <b>Upākarma rite</b> step by step, and <b>Hayagrīva</b>, Lord of learning.','Upākarma (Āvaṇi Aviṭṭam) on Śrāvaṇa Pūrṇimā: the sacred thread (yajñopavīta), the rite of renewal, ṛṣi-tarpaṇa and restarting Veda study, Gāyatrī japa, and Hayagrīva Jayantī. Part 1 of the illustrated Śrāvaṇa Pūrṇimā series.',pp)
i=1
COV=covart('A sister tying a decorated thread on her brother’s wrist, a plate with a lamp, kuṅkuma and sweets, and in the background Lakṣmī tying a thread on King Bali',g(150,196,1.1,person('#c0392b'))+g(230,196,1.1,person('#1d6fb8'))+g(190,140,.8,rakhi())+g(190,196,1,'<ellipse rx="30" ry="6" fill="#e0a800"/>')+g(330,196,.8,devi(sari='#e0a800',items=('lotus',)))+g(390,196,.8,person('#7a3fa0')))
pp=[foreword(i,['On the same full moon as '+pages.link(0,'Upākarma')+', sisters tie a decorated thread, a <b>rākhī</b>, on their brothers’ wrists, and brothers promise to protect them. This is <b>Rakṣā Bandhan</b>, “the bond of protection”.','Its stories are older than the custom’s modern form: a queen protecting her husband, Lakṣmī and King Bali, Draupadī and Kṛṣṇa. On the western coast the same day is <b>Nāraḷī Pūrṇimā</b>, the coconut full moon.'],[('z','Is it only for siblings?'),('b','Today mostly. But the old rakṣā was tied for protection by priests, wives and queens too.')]),
 glance([('When','Śrāvaṇa Pūrṇimā (July–August)'),('Rakṣā','A protective thread tied on the wrist'),('Today','Sisters tie rākhīs on brothers; brothers promise protection and give gifts'),('Old forms','Priests tie rakṣā on patrons; wives on husbands'),('Stories','Indrāṇī and Indra; Lakṣmī and Bali; Draupadī and Kṛṣṇa'),('Coast','Nāraḷī Pūrṇimā: coconuts offered to the sea')],svg(560,140,'A rākhī thread',g(280,90,2,rakhi()))),
 story('indrani','INDRĀṆĪ’S THREAD','The oldest story',strip('Three panels: Indra losing a battle; Indrāṇī preparing a sacred thread with mantras; Indra victorious with the thread on his wrist',[panel([(god('#1d6fb8'),.8),(demon(),.8)],'#e9e3f5',140),panel([(person('#e0a800'),.8),(rakhi(),.8)],'#fff3cf',140),panel([(god('#1d6fb8'),1)],'#cfe0b8',140)],['the gods losing','Indrāṇī’s thread','victory']),'The Bhaviṣya Purāṇa tells this story to explain the rakṣā.',['In a long war the gods were losing to the demons, and Indra was in despair.','His wife <b>Indrāṇī</b> (Śacī), advised by the gods’ teacher Bṛhaspati, prepared a sacred thread, empowered it with mantras on the full moon of Śrāvaṇa.','She tied it on Indra’s wrist.','Protected by it, Indra returned to battle and defeated the demons.','So the rakṣā began as a wife’s protection for her husband, tied with a prayer.'],[('z','A wife, not a sister!'),('b','In the oldest story, yes. The brother-sister form grew later. Protection, love and prayer are the constants.')],'Indrāṇī’s thread wins Indra’s war: <b>the first rakṣā</b>.'),
 story('bali','LAKṢMĪ AND KING BALI','Why the thread binds even God',strip('Three panels: Viṣṇu guarding King Bali’s palace; Lakṣmī tying a thread on Bali’s wrist; Bali releasing Viṣṇu',[panel([(vishnu(),.6),(palace(),.3)],'#dfe9f6',140),panel([(devi(sari='#e0a800',items=('lotus',)),.6),(person('#7a3fa0'),.7)],'#fff3cf',140),panel([(vishnu(),.6),(devi(sari='#e0a800',items=('lotus',)),.6)],'#cfe0b8',140)],['Viṣṇu at Bali’s door','Lakṣmī ties a thread','Bali sets him free']),'A popular telling links the day to Vāmana’s story.',['After Vāmana took the three worlds, he granted the generous Bali the underworld and promised to guard his door himself.','Viṣṇu stayed away so long that Lakṣmī grew lonely in Vaikuṇṭha.','She came to Bali disguised as a poor woman and tied a sacred thread on his wrist, making him her brother.','When Bali offered her any gift, she revealed herself and asked for her husband back.','Bali gladly released Viṣṇu. The thread had bound even the Lord, through love.'],[('z','The thread was stronger than Viṣṇu’s promise?'),('b','Love found a way to free him without breaking his word. That is the story’s gentle cleverness.')],'Lakṣmī’s thread <b>wins her husband back</b>.'),
 reading('draupadi','DRAUPADĪ AND KṚṢṆA','And other stories',svg(560,160,'Draupadī tearing a strip from her sari to bind Kṛṣṇa’s bleeding finger',g(220,150,1.2,person('#c0392b'))+g(340,150,1.2,person('#5a8ad0'))+'<path d="M240 100 q30 -10 80 -10" stroke="#c0392b" stroke-width="4" fill="none"/>'),['<b>Draupadī.</b> A popular story says that when Kṛṣṇa cut his finger, Draupadī tore a strip from her sari and bound it. Kṛṣṇa promised to repay the kindness, and did, when she was humiliated in the Kaurava court and her sari became endless.','<b>A popular tale.</b> This story is not in the critical Mahābhārata in this form; it is a much-loved later telling.','<b>History and legend.</b> Other stories (queens sending rākhīs to kings for protection) are told too; historians question several.','<b>The common thread.</b> Every story is about a bond that obliges protection.'],[('z','Some stories aren’t true?'),('b','Some are legends rather than history. The meaning they carry is still real.')],'A strip of sari, <b>a promise kept</b>.'),
 reading('today','HOW IT IS KEPT TODAY','Sisters, brothers and the coconut full moon',svg(560,170,'A plate with a lamp, rākhīs, kuṅkuma and sweets, and a coconut being offered to the sea',g(180,150,1.3,'<ellipse rx="50" ry="12" fill="#e0a800" stroke="#111"/>')+g(150,130,.6,rakhi())+g(200,125,.8,lamp())+river(560,150,'#5a8ac0')+g(440,120,1.2,'<circle r="16" fill="#8a5a2a" stroke="#111" stroke-width="2"/>')),['<b>The rite.</b> The sister does ārati for her brother, applies a tilaka, ties the rākhī and offers sweets; the brother promises protection and gives a gift.','<b>Beyond blood.</b> Cousins, friends and neighbours tie rākhīs too; soldiers and leaders receive them from many.','<b>Nāraḷī Pūrṇimā.</b> On the Konkan and Karnataka coasts fishing communities offer coconuts to the sea, marking the end of the monsoon pause in fishing.','<b>Upākarma too.</b> In many families, the men change their thread in the morning and receive rākhīs in the afternoon: two bonds, one day.'],[('z','Can a brother tie one on his sister?'),('b','Many families now do it both ways. Protection is mutual.')],'Rākhī, ārati, a promise; <b>coconuts for the sea</b>.'),
 end(i,['<b>Rakṣā.</b> A protective thread tied with love.','<b>Indrāṇī.</b> Her thread won Indra’s war.','<b>Lakṣmī.</b> Her thread made Bali her brother and freed Viṣṇu.','<b>Draupadī.</b> A strip of sari, repaid with endless cloth (popular tale).','<b>Today.</b> Siblings’ bond; Nāraḷī Pūrṇimā on the coast.'],'That completes the Śrāvaṇa Pūrṇimā series. Back to '+pages.link(0,'Upākarma')+', or the <a href="/festivals/">festival calendar</a>.','Rakṣā Bandhan'),
 sources([('Festival:','Wikipedia, “Raksha Bandhan” (Bhaviṣya Purāṇa story of Indrāṇī; Bali and Lakṣmī; historical claims), “Narali Purnima”.')],'the Draupadī story (popular, not in the critical edition); historical rākhī legends (disputed). The rakṣā mantra (“yena baddho balī rājā…”) is not printed here because we could not verify it from an edition.','Described in general terms.')]
build(i,'PART 2 OF 2 · THE THREAD OF PROTECTION',COV,'A thread, a promise','<b>Indrāṇī’s thread</b>, <b>Lakṣmī and Bali</b>, Draupadī’s strip of sari, and <b>how the day is kept</b> today.','Rakṣā Bandhan on Śrāvaṇa Pūrṇimā: the stories of Indrāṇī and Indra, Lakṣmī and King Bali, Draupadī and Kṛṣṇa, how rākhī is tied today, and Nāraḷī Pūrṇimā on the coast. Part 2 of the illustrated Śrāvaṇa Pūrṇimā series.',pp)
# ================= DHANURMĀSA
run_series('/festivals/dhanurmasa/',[('overview','Dhanurmāsa','The Month of Dawn Worship'),('andal-tiruppavai','Āṇḍāḷ and the Tiruppāvai','A Girl’s Vow for the Lord'),('in-temples','Dhanurmāsa in Temples','Tirumala, Śrīraṅgam and the Triraṅga'),('at-home','Dhanurmāsa at Home','Rangoli, Huggi and the Road to Saṅkrānti')],'blue','Dhanurmāsa','Lord','Dhanurmāsa','outx/dhanurmasa/')
i=0
COV=covart('A cold dawn with mist, a temple lamp lit before Viṣṇu, a rangoli at a doorstep, and the constellation of the archer in the sky','<rect width="440" height="196" fill="#cfd8e6"/>'+g(330,196,1.05,vishnu())+g(250,190,1.3,lamp())+g(110,196,1,kolam())+''.join(f'<circle cx="{x}" cy="{y}" r="2" fill="#fff"/>' for x,y in [(60,30),(80,40),(100,36),(120,50),(90,60)]))
pp=[foreword(i,['When the sun enters the sign of Dhanus, the archer, in mid-December, begins <b>Dhanurmāsa</b>, the month before Makara Saṅkrānti. In the south it is a month of <b>dawn worship</b>: temples open before sunrise, the <b>Tiruppāvai</b> is sung, rangolis cover the streets, and hot <b>pongal</b> (huggi) is offered to Viṣṇu.','This 4-part series covers the month, Āṇḍāḷ and her Tiruppāvai, the month in temples (Tirumala, Śrīraṅgam and our Triraṅga), and at home.'],[('z','A whole month of getting up early?'),('b','In the coldest month too. It is said to be the gods’ dawn, so devotees rise with them.')]),
 glance([('When','Sun in Dhanus: about mid-December to Makara Saṅkrānti (mid-January)'),('Tamil','Mārgaḻi'),('Kannada','Dhanurmāsa; Dhanurmāsa pūjā at dawn'),('Worship','Viṣṇu at brāhma muhūrta; Tiruppāvai sung; pongal/huggi offered'),('Great days','Vaikuṇṭha Ekādaśī; Āṇḍāḷ’s wedding on Bhogi'),('Weddings','Not held (counted an inauspicious month for such ceremonies)'),('Ends','Makara Saṅkrānti')],svg(560,140,'A bow and arrow constellation and a rising sun',g(160,110,1.2,bow())+g(400,110,1,sun(20)))),
 reading('month','THE GODS’ DAWN','Why this month',svg(560,170,'A year shown as one day of the gods, with Dhanurmāsa just before their sunrise',g(280,150,1,'<path d="M-200 0 h400" stroke="#111" stroke-width="3"/>')+g(380,150,1,sun(16))+'<rect x="300" y="60" width="70" height="80" fill="#cfd8e6" stroke="#111" stroke-width="2"/>'+lab(335,120,'Dhanurmāsa')+lab(400,175,'Saṅkrānti: gods’ sunrise')),['<b>A day of the gods.</b> Tradition says a human year is one day of the gods: the sun’s northern course (uttarāyaṇa, from Makara Saṅkrānti) is their day, the southern course their night.','<b>Their dawn.</b> Dhanurmāsa, the month just before Saṅkrānti, is thus the gods’ <b>brāhma muhūrta</b>, the sacred hour before dawn. Worship in it is especially praised.','<b>Mārgaśīrṣa.</b> It overlaps with Mārgaśīrṣa, the month Kṛṣṇa calls himself among months (Gītā 10.35).','<b>So we rise early.</b> Worship is done in the cold dark before sunrise, every day of the month.'],[('z','So the whole month is the gods’ early morning?'),('b','Exactly. And what’s more sacred than early-morning prayer?')],'Dhanurmāsa: <b>the gods’ hour before dawn</b>.'),
 reading('practice','THE DAILY PRACTICE','Before sunrise, every day',svg(560,170,'A devotee walking to a temple in the dark carrying a lamp, with a pot of pongal',ground(560,170,150,'#cfd8e6')+g(180,150,1,person('#1d6fb8'))+g(200,110,.8,lamp())+g(380,150,.8,'<path d="M-40 0 h80 l-10 -90 h-60z" fill="#e8c06a" stroke="#111" stroke-width="2"/>')+g(470,140,1,pot_rice())),['<b>Early pūjā.</b> Temples hold special Dhanurmāsa worship before sunrise, and households who keep it do the same at home.','<b>The offering.</b> Hot pongal or huggi (rice and lentils cooked with ghee, pepper and cumin, or sweet with jaggery) is offered to Viṣṇu and shared.','<b>Songs.</b> In Vaiṣṇava homes and temples the Tiruppāvai is sung, one verse a day ('+pages.link(1,'Part 2')+').','<b>Rangoli.</b> Women draw large rangolis (kolam) at the doorstep before dawn ('+pages.link(3,'Part 4')+').'],[('z','Pongal at dawn in the cold?'),('b','Hot ghee pongal on a December morning. Some devotees will tell you that is half the reason they come!')],'Up before dawn: <b>pūjā, pongal, song</b>.'),
 reading('no-weddings','A MONTH WITHOUT WEDDINGS','Śūnya māsa',svg(560,150,'A wedding canopy with a cross, and a temple lamp glowing',g(180,130,1.2,'<path d="M-50 0 v-80 M50 0 v-80 M-60 -80 h120" stroke="#5a8a3a" stroke-width="6" fill="none"/>')+'<path d="M140 50 L220 130 M220 50 L140 130" stroke="#c0392b" stroke-width="5"/>'+g(400,130,1.6,lamp())),['<b>No ceremonies.</b> Dhanurmāsa is counted a <b>śūnya māsa</b>, an “empty month”, for family ceremonies: weddings, house-warmings and the like are generally not held.','<b>Why.</b> The month is given over entirely to God; the gods themselves are in their pre-dawn worship.','<b>Not inauspicious for worship.</b> For devotion, it is one of the best months of the year.','<b>After Saṅkrānti.</b> Ceremonies resume when the sun enters Makara.'],[('z','Empty for weddings, full for God?'),('b','That is exactly the idea.')],'Empty for ceremonies, <b>full for God</b>.'),
 end(i,['<b>When.</b> Sun in Dhanus: mid-December to Saṅkrānti.','<b>Why.</b> The gods’ pre-dawn hour.','<b>Practice.</b> Dawn pūjā, pongal or huggi, the Tiruppāvai.','<b>Weddings.</b> Not held: a śūnya māsa.','<b>Ends.</b> Makara Saṅkrānti.'],'Part 2 tells the story of Āṇḍāḷ, the girl who wrote the Tiruppāvai for this month.','Dhanurmāsa'),
 sources([('Month:','Wikipedia, “Margazhi”, “Dhanurmasa”, “Uttarayana”; Bhagavad Gītā 10.35.')],'regional practices; the “gods’ day” idea in detail (stated variously in the Purāṇas).','No dates or timings given.')]
build(i,'PART 1 OF 4 · DAWN · PONGAL · THE ARCHER',COV,'The month of dawn worship','<b>Why this month</b> is the gods’ dawn, the <b>daily practice</b>, and why it is a month <b>without weddings</b>.','Dhanurmāsa explained: the month of the sun in Dhanus before Makara Saṅkrānti, the gods’ pre-dawn hour, daily dawn worship with pongal and the Tiruppāvai, and why it is a śūnya māsa. Part 1 of the illustrated Dhanurmāsa series.',pp)
i=1
AND=lambda: devi(sari='#2a9d6f',items=('lotus',),crown='#e0a800',halo='#fff3b0',third_eye=False)
COV=covart('The young saint Āṇḍāḷ in green with a parrot on her hand and a tilted hair-knot, a garland, and Raṅganātha reclining in the background',g(150,196,1.3,AND())+g(178,110,.8,'<path d="M0 0 q-10 -20 6 -26 q12 4 4 22z" fill="#2a9d6f" stroke="#111" stroke-width="2"/>')+g(330,190,.8,sheshashayi()))
pp=[foreword(i,['The song of Dhanurmāsa is the <b>Tiruppāvai</b>, thirty Tamil verses composed by <b>Āṇḍāḷ</b>, the only woman among the twelve Āḻvār saints. In it a young girl wakes her friends before dawn in the month of Mārgaḻi to go and worship Kṛṣṇa together.','Our <a href="/vishnu/tiruppavai/">Tiruppāvai series</a> reads all thirty verses. Here is Āṇḍāḷ’s story and why her song belongs to this month.'],[('z','A girl wrote the month’s great hymn?'),('b','A girl of about fifteen, the tradition says. Her verses are sung in every Viṣṇu temple of the south.')]),
 glance([('Who','Āṇḍāḷ (Kōtai), the only woman Āḻvār'),('Where','Śrīvilliputtūr, Tamil Nadu'),('Father','Periyāḻvār (Viṣṇucitta), himself an Āḻvār'),('Works','Tiruppāvai (30 verses); Nācciyār Tirumoḻi (143 verses)'),('Sung','One Tiruppāvai verse a day through Mārgaḻi/Dhanurmāsa'),('Wedding','Āṇḍāḷ’s marriage to Raṅganātha celebrated on Bhogi')],svg(560,140,'Āṇḍāḷ with a parrot',g(280,135,1,AND()))),
 story('garland','THE GARLAND SHE WORE FIRST','Āṇḍāḷ’s story',strip('Three panels: a baby found under a tulasī plant; a girl wearing a garland before a mirror; the father finding a hair in the garland',[panel([(tulasi(),.8),(child(),.8)],'#cfe0b8',140),panel([(AND(),.7),('<rect x="-12" y="-50" width="24" height="34" fill="#dfe9f6" stroke="#111"/>',1)],'#fff3cf',140),panel([(sage('#ff8c1a'),.8),(AND(),.6)],'#fde4e4',140)],['found under the tulasī','trying on God’s garland','“she who ruled”']),'The Śrīvaiṣṇava tradition tells her story with deep affection.',['<b>Periyāḻvār</b>, a devotee who made flower garlands for the Lord at Śrīvilliputtūr, found a baby girl under a tulasī plant in his garden. He named her <b>Kōtai</b> and raised her on stories of Kṛṣṇa.','As she grew, she longed to marry the Lord. Secretly she wore the garlands meant for him, looking in a mirror to see if she was fit to be his bride.','One day Periyāḻvār found a hair in the garland and, horrified, made a fresh one. That night the Lord told him in a dream that he wanted only the garlands she had worn.','She became <b>Āṇḍāḷ</b>, “she who ruled (the Lord)”, and <b>Cūḍikkoḍutta Nācciyār</b>, “the lady who gave the garland she had worn”.','At last she was taken as a bride to Raṅganātha at Śrīraṅgam, where, the tradition says, she merged with the Lord.'],[('z','God wanted the used garland?'),('b','Because of the love in it. The story turns a “mistake” into the highest offering.')],'The garland worn first: <b>Āṇḍāḷ, who ruled the Lord</b>.'),
 reading('song','THE SONG OF THE MONTH','What the Tiruppāvai is',svg(560,170,'Girls walking together before dawn to a river, calling at each door',ground(560,170,150,'#cfd8e6')+''.join(g(120+k*60,150,.9,person(c)) for k,c in enumerate(['#2a9d6f','#c0392b','#e0a800','#7a3fa0','#1d6fb8']))+river(560,160)),['<b>A vow.</b> The Tiruppāvai is about a <b>pāvai nōnbu</b>, a girls’ vow kept in Mārgaḻi: bathing before dawn, simple living, and going together to worship Kṛṣṇa.','<b>Waking friends.</b> Many verses are wake-up calls at a friend’s door: “Get up! The birds are singing, the conch is sounding!”','<b>At Kṛṣṇa’s door.</b> Then they wake Nanda’s household and Kṛṣṇa himself, and ask not for wealth but to serve him for ever.','<b>Every day of the month.</b> Thirty verses for the thirty days of Mārgaḻi; temples and homes sing the day’s verse at dawn.'],[('z','Like the gopīs’ Kātyāyanī vow?'),('b','Very like it, consciously. Āṇḍāḷ imagines herself as a gopī of Vraja keeping the Mārgaśīrṣa vow.')],'Thirty verses, <b>thirty dawns</b>.'),
 reading('vow','WHAT ĀṆḌĀḶ ASKS','The heart of the Tiruppāvai',svg(560,160,'A girl with folded hands before Kṛṣṇa, who smiles',g(220,150,1.1,AND())+g(360,150,1.2,person('#5a8ad0'))),['<b>Not wealth.</b> At the end of the song the girls ask Kṛṣṇa not for the drum (paṟai) or the gifts of the vow, but to be his for ever, in every birth.','<b>Together.</b> The vow is never kept alone: the girls wake each other. Devotion, Āṇḍāḷ suggests, is a community.','<b>Women’s voice.</b> As the only woman Āḻvār, Āṇḍāḷ gives the tradition a woman’s voice of longing and confidence.','<b>Read it.</b> Our <a href="/vishnu/tiruppavai/">Tiruppāvai series</a> gives each verse with meaning.'],[('z','So the vow’s reward is just to serve him?'),('b','That is the reward, she says. Everything else was a pretext.')],'Āṇḍāḷ asks <b>only to be his</b>.'),
 end(i,['<b>Āṇḍāḷ.</b> The only woman Āḻvār, of Śrīvilliputtūr.','<b>Story.</b> She wore God’s garland first; he wanted only hers.','<b>Tiruppāvai.</b> Thirty verses for the thirty dawns of Mārgaḻi.','<b>Vow.</b> Girls waking each other to go to Kṛṣṇa.','<b>Heart.</b> To be his for ever.'],'Part 3 visits the temples in Dhanurmāsa: Tirumala, Śrīraṅgam and our own Triraṅga.','Āṇḍāḷ and the Tiruppāvai'),
 sources([('Saint:','Wikipedia, “Andal”, “Tiruppavai”, “Periyalvar”, “Srivilliputhur Andal Temple”; our Tiruppāvai series.')],'traditional dates and details of Āṇḍāḷ’s life (hagiographical).','Story told as the tradition tells it.')]
build(i,'PART 2 OF 4 · THE GIRL SAINT · THIRTY DAWNS',COV,'The garland she wore first','<b>Āṇḍāḷ’s story</b> and the garland, what the <b>Tiruppāvai</b> is, and <b>what she asks</b> of the Lord.','Āṇḍāḷ and the Tiruppāvai in Dhanurmāsa: the story of the girl saint of Śrīvilliputtūr who wore the Lord’s garland, the pāvai vow of thirty dawns, and the heart of her song. Part 2 of the illustrated Dhanurmāsa series.',pp)
i=2
COV=covart('A temple tower at dawn with priests singing, the reclining Raṅganātha, and an open golden gate',g(110,196,1,'<path d="M-40 0 h80 l-14 -120 h-52z" fill="#e8c06a" stroke="#111" stroke-width="2"/>')+g(240,180,1,sheshashayi())+g(380,196,1,'<path d="M-40 0 v-90 q40 -30 80 0 v90z" fill="#e0a800" stroke="#111" stroke-width="2"/>'))
pp=[foreword(i,['In Dhanurmāsa the great Viṣṇu temples of the south change their rhythm. At <b>Tirumala</b> the Tiruppāvai replaces the Suprabhātam at dawn; at <b>Śrīraṅgam</b> the long <b>Adhyayana Utsavam</b> recites the Āḻvārs’ hymns and opens the Vaikuṇṭha gate; and in Karnataka the <b>Triraṅga</b> temples keep the month with dawn worship.','This part visits them. It gives no timings; temples publish their own each year.'],[('z','The Suprabhātam stops?'),('b','At Tirumala, in this month, Āṇḍāḷ’s verses wake the Lord instead. A remarkable honour for a girl’s song.')]),
 glance([('Tirumala','Tiruppāvai sung in place of the Venkaṭeśa Suprabhātam during Dhanurmāsa'),('Śrīraṅgam','Adhyayana Utsavam (pagal pattu and rā pattu); Vaikuṇṭha Ekādaśī’s Paramapada vāsal'),('Śrīvilliputtūr','Āṇḍāḷ’s own temple; her festival of the month'),('Karnataka','Dhanurmāsa pūjā at dawn; Śrīraṅgapaṭṇa, Śivanasamudra and the Triraṅga'),('Bhogi','Āṇḍāḷ’s wedding (Āṇḍāḷ Kalyāṇam) in many temples')],svg(560,140,'Three temple towers',''.join(g(140+k*140,130,.9,'<path d="M-36 0 h72 l-12 -100 h-48z" fill="#e8c06a" stroke="#111" stroke-width="2"/>') for k in range(3)))),
 reading('tirumala','TIRUMALA','When Āṇḍāḷ wakes the Lord',svg(560,170,'The Lord of Tirumala in his shrine with priests singing before dawn',g(280,160,1.2,vishnu())+g(160,160,.9,sage('#f4f1ea'))+g(400,160,.9,sage('#f4f1ea'))),['<b>No Suprabhātam.</b> Every other morning of the year the <a href="/vishnu/venkatesa-suprabhatam/">Venkaṭeśa Suprabhātam</a> wakes the Lord at Tirumala. In Dhanurmāsa it is replaced by Āṇḍāḷ’s <b>Tiruppāvai</b>.','<b>Why.</b> In the Śrīvaiṣṇava tradition the Tamil hymns of the Āḻvārs are counted equal to the Veda, and in Mārgaḻi Āṇḍāḷ’s waking songs are the right ones to wake the Lord.','<b>Tulasī and Bilva.</b> Special offerings and arrangements mark the month at the temple.','<b>Vaikuṇṭha Ekādaśī.</b> The Vaikuṇṭha dvāra at Tirumala opens for the great Ekādaśī within the month; see our <a href="/festivals/vaikuntha-ekadashi/">Vaikuṇṭha Ekādaśī article</a>.'],[('z','A girl’s song instead of a Sanskrit one?'),('b','Exactly. That’s how highly the tradition holds her.')],'At Tirumala, <b>Āṇḍāḷ wakes the Lord</b>.'),
 reading('srirangam','ŚRĪRAṄGAM','The festival of recitation',svg(560,170,'Raṅganātha reclining, with priests reciting from palm leaves over many days, and a golden gate',g(220,150,1,sheshashayi())+''.join(g(x,165,.7,sage('#f4f1ea')) for x in (380,420,460))+g(520,165,.6,'<path d="M-30 0 v-70 q30 -20 60 0 v70z" fill="#e0a800" stroke="#111"/>')),['<b>Adhyayana Utsavam.</b> At Śrīraṅgam, Dhanurmāsa brings the <b>Adhyayana Utsavam</b>, about twenty days of reciting the Āḻvārs’ 4,000 verses (the Nālāyira Divya Prabandham): ten days before Vaikuṇṭha Ekādaśī (<i>pagal pattu</i>) and ten after (<i>rā pattu</i>).','<b>The gate.</b> On Vaikuṇṭha Ekādaśī the <b>Paramapada vāsal</b>, the northern gate, opens and Namperumāḷ passes through it.','<b>Āṇḍāḷ’s groom.</b> Raṅganātha is the Lord Āṇḍāḷ married ('+pages.link(1,'Part 2')+').','<b>Our series.</b> See our <a href="/temples-of-india/tamil-nadu/">Temples of Tamil Nadu</a> and <a href="/festivals/vaikuntha-ekadashi/">Vaikuṇṭha Ekādaśī</a>.'],[('z','Twenty days of recitation?'),('b','4,000 Tamil verses, sung in procession before the Lord. It is one of the great festivals of the Vaiṣṇava world.')],'Śrīraṅgam: <b>twenty days of the Āḻvārs’ verses</b>.'),
 reading('triranga','THE TRIRAṄGA IN DHANURMĀSA','Karnataka’s Raṅganāthas',svg(560,170,'The Kāverī with three temples along it',river(560,120)+''.join(g(120+k*160,110,.7,'<path d="M-36 0 h72 l-12 -80 h-48z" fill="#e8c06a" stroke="#111" stroke-width="2"/>') for k in range(3))+''.join(lab(120+k*160,160,t) for k,t in enumerate(['Śrīraṅgapaṭṇa','Śivanasamudra','Śrīraṅgam']))),['<b>Three Raṅganāthas.</b> Along the Kāverī lie the three great Raṅganātha shrines: Ādi Raṅga at Śrīraṅgapaṭṇa, Madhya Raṅga at Śivanasamudra and Antya Raṅga at Śrīraṅgam. Our <a href="/temples-of-india/triranga/">Triraṅga series</a> visits each.','<b>Dawn worship.</b> Through Dhanurmāsa, Śrīraṅgapaṭṇa and other Karnataka Vaiṣṇava temples hold Dhanurmāsa pūjā before sunrise, with pongal offered and shared.','<b>Vaikuṇṭha Ekādaśī.</b> The northern gate (Vaikuṇṭha dvāra) opens at Śrīraṅgapaṭṇa and other temples on the great Ekādaśī.','<b>Melukōṭe and more.</b> Śrīvaiṣṇava centres in Karnataka, such as Melukōṭe, keep the month with the Tiruppāvai; see our <a href="/temples-of-india/around-mysuru/melukote/">Melukōṭe article</a>.'],[('z','So Mysuru has its own Dhanurmāsa?'),('b','At Śrīraṅgapaṭṇa, twenty kilometres away. Raṅganātha is the Lord of the month.')],'Karnataka’s Raṅganāthas: <b>dawn worship and the northern gate</b>.'),
 reading('kalyanam','ĀṆḌĀḶ’S WEDDING','Bhogi',svg(560,170,'Āṇḍāḷ and Raṅganātha seated together as bride and groom under a canopy',g(280,160,1.2,'<path d="M-90 0 v-120 M90 0 v-120 M-100 -120 h200" stroke="#5a8a3a" stroke-width="6" fill="none"/>')+g(240,160,1,AND())+g(320,160,1,vishnu())),['<b>On Bhogi.</b> On the last day of Dhanurmāsa, Bhogi, the eve of Makara Saṅkrānti, many Vaiṣṇava temples celebrate <b>Āṇḍāḷ Kalyāṇam</b>, Āṇḍāḷ’s wedding to Raṅganātha.','<b>Her own hymn.</b> Her Nācciyār Tirumoḻi includes a famous dream of her own wedding (Vāraṇamāyiram), sung at Śrīvaiṣṇava weddings to this day.','<b>The month’s end.</b> The wedding completes the month that her Tiruppāvai began.','<b>Then Saṅkrānti.</b> The next day the sun enters Makara; see our <a href="/festivals/makara-sankranti/">Saṅkrānti article</a>.'],[('z','The girl gets her wish at the end of the month?'),('b','Every year. The month is her love story, ending in a wedding.')],'On Bhogi, <b>Āṇḍāḷ weds Raṅganātha</b>.'),
 end(i,['<b>Tirumala.</b> The Tiruppāvai replaces the Suprabhātam.','<b>Śrīraṅgam.</b> Adhyayana Utsavam; the Paramapada gate.','<b>Karnataka.</b> Triraṅga dawn worship and the Vaikuṇṭha dvāra.','<b>Śrīvilliputtūr.</b> Āṇḍāḷ’s own temple.','<b>Bhogi.</b> Āṇḍāḷ’s wedding.'],'Part 4 comes home: the rangoli at the doorstep, huggi in the pot, and the road to Saṅkrānti.','Dhanurmāsa in temples'),
 sources([('Temples:','Wikipedia, “Tiruppavai” (Tirumala custom), “Ranganathaswamy Temple, Srirangam” (Adhyayana Utsavam, Vaikuṇṭha Ekādaśī), “Andal” (Āṇḍāḷ Kalyāṇam), “Srirangapatna”; our Triraṅga series.')],'temple-specific customs vary and change; no timings are given.','No timings given; check each temple’s announcements.')]
build(i,'PART 3 OF 4 · TIRUMALA · ŚRĪRAṄGAM · TRIRAṄGA',COV,'Temples at dawn','<b>Tirumala</b>, where Āṇḍāḷ wakes the Lord, <b>Śrīraṅgam</b>’s festival of recitation, Karnataka’s <b>Triraṅga</b>, and <b>Āṇḍāḷ’s wedding</b>.','Dhanurmāsa in temples: the Tiruppāvai replacing the Suprabhātam at Tirumala, Śrīraṅgam’s Adhyayana Utsavam and Paramapada gate, the Triraṅga temples of the Kāverī, and Āṇḍāḷ Kalyāṇam on Bhogi. Part 3 of the illustrated Dhanurmāsa series.',pp)
i=3
COV=covart('A large white rangoli at a doorstep at dawn with a pumpkin flower in cow-dung at its centre, and a steaming pot of huggi',ground(440,220,160,'#e9d6c0')+g(160,190,1.8,kolam()).replace('#fff','#fff')+g(160,190,1,'<circle r="8" fill="#e0a800" stroke="#111"/>')+g(330,190,1.4,pot_rice())+g(330,140,1,'<path d="M-10 0 q-4 -14 4 -24 M10 0 q4 -14 -4 -24" stroke="#999" stroke-width="2" fill="none"/>'))
pp=[foreword(i,['In homes across the south, Dhanurmāsa is felt before it is seen: women up before dawn drawing huge <b>rangolis</b> (kolam) in the cold, the smell of <b>huggi</b> or pongal, the Tiruppāvai on the radio. This last part is about the month at home, and how it leads into Makara Saṅkrānti.'],[('z','Why so much rangoli in this month?'),('b','It welcomes the Lord and Lakṣmī at the gods’ dawn. And it is the most beautiful month for it: cold, clear mornings.')]),
 glance([('Rangoli','Large kolam/rangoli drawn before dawn each day'),('Flower','A pumpkin flower set in a small cow-dung cone at the centre (Tamil custom)'),('Huggi','Pongal: rice and moong dal with ghee, pepper and cumin, or sweet with jaggery'),('Songs','The day’s Tiruppāvai verse; Viṣṇu’s names'),('No ceremonies','Weddings and house-warmings postponed'),('Ends','Bhogi, then Makara Saṅkrānti')],svg(560,140,'A rangoli and a pot',g(200,90,1.8,kolam())+g(400,120,1.4,pot_rice()),bg='#8a6a4a')),
 reading('kolam','THE DAWN RANGOLI','Kolam in Mārgaḻi',svg(560,190,'A doorstep with a large dotted rangoli design spread in front of it',ground(560,190,40,'#8a6a4a')+g(280,120,3,kolam())+'<rect x="230" y="0" width="100" height="40" fill="#8a5a3a" stroke="#111" stroke-width="2"/>',bg='#8a6a4a'),['<b>Big and daily.</b> Through the month women draw especially large rangolis at the threshold before dawn, often competing street by street.','<b>Dots and lines.</b> Many kolams are drawn by laying a grid of dots and looping lines around them in rice flour, which also feeds ants and birds.','<b>The pumpkin flower.</b> In Tamil homes a yellow pumpkin flower is set in a small cone of cow dung at the centre, and the dried flowers are saved and later floated in water.','<b>Welcome.</b> The rangoli welcomes the Lord and Lakṣmī and wards off misfortune.'],[('z','Rice flour feeds the ants?'),('b','That is the old custom: the design is also a gift to small creatures. Beauty and kindness together.')],'Rice-flour rangolis <b>at every door, every dawn</b>.'),
 reading('huggi','HUGGI AND PONGAL','The offering of the month',svg(560,170,'Two bowls, one of savoury pongal with pepper and cumin, one of sweet pongal with jaggery and cashews',g(180,140,1.4,'<ellipse rx="50" ry="14" fill="#f3e3c3" stroke="#111" stroke-width="2"/>'+''.join(f'<circle cx="{x}" cy="-6" r="2" fill="#111"/>' for x in (-20,-6,8,20)))+g(400,140,1.4,'<ellipse rx="50" ry="14" fill="#c98a3a" stroke="#111" stroke-width="2"/>'+''.join(f'<circle cx="{x}" cy="-6" r="3" fill="#f3e3c3"/>' for x in (-20,0,20)))+lab(180,170,'khāra (savoury) huggi')+lab(400,170,'sihi (sweet) huggi')),['<b>Huggi.</b> In Karnataka the Dhanurmāsa offering is <b>huggi</b>: rice and moong dal cooked soft with ghee, pepper, cumin and ginger (khāra huggi), or with jaggery and coconut (sihi huggi). In Tamil Nadu it is <b>ven pongal</b> and <b>sakkarai pongal</b>.','<b>Offered at dawn.</b> It is cooked fresh before sunrise and offered hot to Viṣṇu, then shared as prasāda.','<b>Temples.</b> Temples distribute it to all who come for the dawn worship.','<b>Warmth.</b> Hot ghee, pepper and ginger: food for a cold month.'],[('z','The same dish all month?'),('b','The same, every dawn, and nobody complains. Ask anyone who has stood in a temple queue for Dhanurmāsa huggi.')],'Hot huggi at dawn: <b>Dhanurmāsa’s offering</b>.'),
 reading('sankranti','THE ROAD TO SAṄKRĀNTI','Bhogi and the sun’s turn',svg(560,170,'A bonfire for Bhogi on the left and the sun rising into the north on the right, with sugarcane',g(150,160,1.4,flames())+g(400,90,1.2,sun(20))+g(480,160,1,'<path d="M0 0 v-120" stroke="#5a8a3a" stroke-width="6"/>')),['<b>Bhogi.</b> The last day of the month is <b>Bhogi</b>: old things are burnt in a bonfire at dawn, homes are cleaned, and in temples Āṇḍāḷ weds Raṅganātha ('+pages.link(2,'Part 3')+').','<b>Saṅkrānti.</b> The next day the sun enters Makara and turns north: the gods’ day begins. In Karnataka it is <b>Saṅkrānti</b>, with eḷḷu-bella (sesame and jaggery) exchanged: “eat sesame and jaggery, speak sweetly”. See our <a href="/festivals/makara-sankranti/">Makara Saṅkrānti article</a>.','<b>Ceremonies resume.</b> With the sun in Makara, weddings and house-warmings are held again.','<b>The cycle.</b> From the gods’ pre-dawn to their sunrise: Dhanurmāsa is the waiting, Saṅkrānti the dawn.'],[('z','So the month ends with a bonfire and sweets?'),('b','A bonfire for the old, sweets for the new. A good ending.')],'Bhogi’s fire, Saṅkrānti’s sun: <b>the month’s end</b>.'),
 end(i,['<b>Rangoli.</b> Large rice-flour kolams every dawn.','<b>Flower.</b> The pumpkin flower at the centre (Tamil custom).','<b>Huggi.</b> Savoury and sweet, offered hot at dawn.','<b>Bhogi.</b> Bonfire of the old; Āṇḍāḷ’s wedding.','<b>Saṅkrānti.</b> The sun turns north; sesame and jaggery.'],'That completes the Dhanurmāsa series. Back to '+pages.link(0,'Part 1')+', or to our <a href="/vishnu/tiruppavai/">Tiruppāvai</a>.','Dhanurmāsa at home'),
 sources([('Customs:','Wikipedia, “Kolam”, “Margazhi”, “Pongal (dish)”, “Bhogi”, “Makar Sankranti”.')],'household customs vary by region and family.','Customs in general forms.')]
build(i,'PART 4 OF 4 · RANGOLI · HUGGI · BHOGI',COV,'The doorstep and the pot','The <b>dawn rangoli</b>, <b>huggi and pongal</b>, and the <b>road to Saṅkrānti</b> through Bhogi.','Dhanurmāsa at home: the daily dawn rangoli (kolam), huggi and pongal offered to Viṣṇu, Bhogi and the road to Makara Saṅkrānti. Part 4 of the illustrated Dhanurmāsa series.',pp)
